	_ "github.com/mattn/go-sqlite3"
)

func main() {
	app := fiber.New(fiber.Config{DisableStartupMessage: true})

	// Connect to SQLite database
	db, err := sql.Open("sqlite3", "db.sqlite3")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	// Create tables if they don't exist
	createTables(db)

