   ```go
   func Authorize(c *fiber.Ctx) error {
       authHeader := c.Get("Authorization")
       if authHeader == "" {
           return c.Status(fiber.StatusUnauthorized).JSON(fiber.Map{"message": "Invalid authentication token"})
