package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"

	"github.com/google/uuid"
	_ "github.com/mattn/go-sqlite3"
)

var db *sql.DB

func initDB() {
	var err error
	db, err = sql.Open("sqlite3", "./db.sqlite3")
	if err != nil {
		log.Fatalf("Failed to open database: %v", err)
	}

	createCartTable := `CREATE TABLE IF NOT EXISTS carts (
		id TEXT PRIMARY KEY
	);`
	_, err = db.Exec(createCartTable)
	if err != nil {
		log.Fatalf("Failed to create carts table: %v", err)
	}

	createItemsTable := `CREATE TABLE IF NOT EXISTS cart_items (
		cart_id TEXT,
		item_id INTEGER,
		count INTEGER,
		PRIMARY KEY (cart_id, item_id),
		FOREIGN KEY (cart_id) REFERENCES carts(id)
	);`
	_, err = db.Exec(createItemsTable)
	if err != nil {
		log.Fatalf("Failed to create cart_items table: %v", err)
	}
}

func createCartHandler(w http.ResponseWriter, r *http.Request) {
	cartID := uuid.New().String()
	_, err := db.Exec("INSERT INTO carts (id) VALUES (?)", cartID)
	if err != nil {
		http.Error(w, "Failed to create cart", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(map[string]string{"cart_id": cartID})
}

func addToCartHandler(w http.ResponseWriter, r *http.Request) {
	var req struct {
		CartID string `json:"cart_id"`
		ItemID int    `json:"item_id"`
		Count  int    `json:"count"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request", http.StatusBadRequest)
		return
	}

	var exists bool
	err := db.QueryRow("SELECT EXISTS(SELECT 1 FROM carts WHERE id=?)", req.CartID).Scan(&exists)
	if err != nil || !exists {
		http.Error(w, "Cart not found", http.StatusNotFound)
		return
	}

	_, err = db.Exec("INSERT INTO cart_items (cart_id, item_id, count) VALUES (?, ?, ?) ON CONFLICT(cart_id, item_id) DO UPDATE SET count=count+excluded.count", req.CartID, req.ItemID, req.Count)
	if err != nil {
		http.Error(w, "Failed to update cart", http.StatusInternalServerError)
		return
	}

