  });

  await db.run(`CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    email TEXT UNIQUE,
    username TEXT UNIQUE,
    password TEXT
  )`);

  await db.run(`CREATE TABLE IF NOT EXISTS secrets (
    id TEXT PRIMARY KEY,
    username TEXT,
    secret TEXT,
    FOREIGN KEY(username) REFERENCES users(username)
  )`);
})();

