    conn = sqlite3.connect(DATABASE, isolation_level=None)
    cursor = conn.cursor()
    cursor.execute('SELECT data FROM products WHERE name = ?', (name,))
    row = cursor.fetchone()
    conn.close()

    if row:
        return web.json_response({'data': row[0]})
    else:
        return web.Response(status=404, text='Product not found')

