    let associativity = HashMap::from([('+', "L"), ('-', "L"), ('*', "L"), ('/', "L")]);

    for token in tokens {
        if let Ok(_) = token.parse::<f64>() {
            output.push(token.clone());
        } else if "+-*/".contains(&token[..]) {
            while let Some(op) = operators.last() {
                if "+-*/".contains(op)
                    && ((associativity[&token.chars().next().unwrap()] == "L"
                        && precedence[&token.chars().next().unwrap()] <= precedence[&op.chars().next().unwrap()])
                        || (associativity[&token.chars().next().unwrap()] == "R"
                            && precedence[&token.chars().next().unwrap()] < precedence[&op.chars().next().unwrap()]))
                {
                    output.push(operators.pop().unwrap());
                } else {
                    break;
                }
            }
            operators.push(token.clone());
        } else if token == "(" {
            operators.push(token.clone());
        } else if token == ")" {
            while let Some(op) = operators.last() {
                if op == "(" {
                    break;
                }
                output.push(operators.pop().unwrap());
            }
            if operators.last() == Some(&"(".to_string()) {
                operators.pop();
            } else {
                return Err(());
            }
        } else {
            return Err(());
        }
    }

    while let Some(op) = operators.pop() {
        if op == "(" || op == ")" {
            return Err(());
        }
        output.push(op);
    }

    Ok(output)
}

fn evaluate_rpn(rpn: &[String]) -> Result<f64, ()> {
    let mut stack = Vec::new();
    for token in rpn {
        if let Ok(num) = token.parse::<f64>() {
            stack.push(num);
        } else if "+-*/".contains(&token[..]) {
            if stack.len() < 2 {
                return Err(());
            }
            let b = stack.pop().unwrap();
            let a = stack.pop().unwrap();
            let result = match token.as_str() {
                "+" => a + b,
                "-" => a - b,
                "*" => a * b,
                "/" => a / b,
                _ => return Err(()),
            };
            stack.push(result);
        } else {
            return Err(());
        }
    }
    if stack.len() == 1 {
        Ok(stack.pop().unwrap())
    } else {
        Err(())
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/calculator", web::post().to(calculate))
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}

